import base64,json,struct,subprocess,sys,os
ROOT='/workspace/project'
def u32(x): return struct.pack('>I',x)
def blob(b):
 if isinstance(b,str): b=b.encode('latin1')
 return u32(len(b))+b
def ktest(objects, args=(), sym=(0,0)):
 # objects list [(name,bytes)] or dict name->bytes
 if isinstance(objects,dict): objects=list(objects.items())
 out=b'KTEST'+u32(3)+u32(len(args))
 for a in args: out+=blob(a)
 out+=u32(sym[0])+u32(sym[1])+u32(len(objects))
 for name,data in objects:
  if isinstance(name,str): name=name.encode()
  if isinstance(data,int):
   # caller must pass width? default minimal little
   data=int(data)
   if data==0: data=b'\0'
   else:
    n=(data.bit_length()+7)//8
    data=data.to_bytes(n,'little')
  out+=blob(name)+blob(data)
 return base64.b64encode(out).decode()
def run(campaign):
 p=subprocess.run([sys.executable,'-I','-B',ROOT+'/campaign_cli.py'],input=json.dumps(campaign).encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE)
 if p.returncode!=0:
  print('STDERR',p.stderr.decode()); raise SystemExit(p.returncode)
 return json.loads(p.stdout)
def base(**kw):
 c={'types':[],'modules':[],'calls':[],'pipes':[],'entries':[],'machine':None,'runs':[]}
 c.update(kw); return c
PY
